-- Replace Erdogan's personal era-based yield bonuses with +15% in the current capital.
DELETE FROM TraitModifiers WHERE TraitType='TRAIT_LEADER_ERDOGAN';
INSERT OR IGNORE INTO Modifiers (ModifierId, ModifierType) VALUES ('BBC_ERDOGAN_CAPITAL_FOOD', 'MODIFIER_PLAYER_CAPITAL_CITY_ADJUST_CITY_YIELD_MODIFIER');
INSERT OR IGNORE INTO ModifierArguments (ModifierId, Name, Value) VALUES ('BBC_ERDOGAN_CAPITAL_FOOD', 'YieldType', 'YIELD_FOOD'), ('BBC_ERDOGAN_CAPITAL_FOOD', 'Amount', 15);
INSERT OR IGNORE INTO TraitModifiers (TraitType, ModifierId) SELECT TraitType, 'BBC_ERDOGAN_CAPITAL_FOOD' FROM Traits WHERE TraitType='TRAIT_LEADER_ERDOGAN';
